#include <lean/lean.h>

/*
 * Audit-environment workaround: the mounted Lean 4.22 binary cannot resolve
 * IO.appPath, although its immutable sysroot is present.  Return that exact
 * pinned binary path so Lake can exercise the generated project.
 */
LEAN_EXPORT lean_obj_res lean_io_app_path(lean_obj_arg world) {
    (void)world;
    return lean_io_result_mk_ok(
        lean_mk_string(
            "/opt/elan/toolchains/leanprover--lean4---v4.22.0/bin/lean"
        )
    );
}

